// 은행 → 표(id → { c 갈래, t 이름, src, q, sk })
export const BANK = {};
for (const [id, c, t, src, q, sk] of B) BANK[id] = { c, t, src, q, sk: sk || CATS[c].sk };
export const IDS = B.map(r => r[0]);
// 지나가는 글 열쇠 → 개념들(saw:열쇠)
const SAW = {};
for (const id of IDS) for (const s of BANK[id].src) if (s.startsWith('saw:')) (SAW[s.slice(4)] = SAW[s.slice(4)] || []).push(id);
// 출처가 이미 일어났나 → 그날(아니면 0) · 상태만 봄(saw는 따로)
function srcDay(S, s) {
  const day = S.day || 1;
  if (s.startsWith('dex:')) { const v = (S.dex || {})[s.slice(4)]; return v == null ? 0 : typeof v === 'number' ? v : (v.d || day); }
  if (s.startsWith('dexp:')) { const p = s.slice(5), D = S.dex || {}; for (const k in D) if (k.startsWith(p)) { const v = D[k]; return typeof v === 'number' ? v : (v && v.d) || day; } return 0; }
  if (s.startsWith('card:') || s.startsWith('lv:')) { const [, k, L] = s.split(':'); return lv(S, k) >= +L ? day : 0; }
  if (s.startsWith('st:')) { const d = S.story && S.story.done && S.story.done[s.slice(3)]; return d ? (d.d || day) : 0; }
  if (s === 'pol') return S.pol > 0 ? S.pol : 0;
  if (s.startsWith('learn:')) { const r = S.learn && S.learn[s.slice(6)]; return r ? (r.d || day) : 0; }   /* 같은 자리에서 함께 배운 것(아쿠아리움 쇼) */
  return 0;
}
const rec0 = d => ({ d, box: 1, ok: 0, ng: 0 });
// 상태를 훑어 새로 배운 개념을 남김 → 새 id 목록(없으면 null)
export function scanLearn(S) { const L = S.learn || (S.learn = {}); let neu = null;
  for (const id of IDS) { if (L[id]) continue; for (const s of BANK[id].src) { const d = srcDay(S, s); if (d) { L[id] = rec0(Math.min(d, S.day || d)); (neu = neu || []).push(id); break; } } }
  return neu; }
// 지나가는 글을 봄 → 새 id 목록
export function sawLearn(S, key) { const ids = SAW[key]; if (!ids) return null; const L = S.learn || (S.learn = {}); let neu = null; for (const id of ids) if (!L[id]) { L[id] = rec0(S.day || 1); (neu = neu || []).push(id); } return neu; }
// 간격 반복
export const IV = [0, 1, 2, 4, 7, 14];   // 상자 → 다시 묻기까지 날
export const starOf = r => Math.min(3, (r && r.ok) || 0);
export const stars = r => { const n = starOf(r); return '★★★'.slice(0, n) + '☆☆☆'.slice(0, 3 - n); };
export const dueOf = r => (r.at ? r.at + IV[Math.min(5, Math.max(1, r.box || 1))] : r.d);
const hs = s => { let h = 7; for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0; return h >>> 0; };
export function dueList(S, day) { const L = S.learn || {}, out = [];
  for (const id in L) { const r = L[id]; if (!BANK[id] || !r || r.at === day) continue; if (dueOf(r) <= day) out.push(id); }
  return out.sort((a, b) => (dueOf(L[a]) - dueOf(L[b])) || (L[a].box - L[b].box) || (hs(a + day) - hs(b + day))); }   /* 차례가 오래된 것부터(밀린 것이 굶지 않게) · 같으면 낮은 상자 먼저 */
